WITH sessions_by_customer AS (SELECT customer_id, SUM(CASE WHEN browser = 'Chrome' THEN 1 ELSE 0 END) AS chrome_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(device))) AS device_values FROM sessions WHERE customer_id = 5 GROUP BY customer_id) SELECT c.id, c.signup_date, c.age, sbc.chrome_count, sbc.device_values FROM customers c JOIN sessions_by_customer sbc ON c.id = sbc.customer_id WHERE sbc.chrome_count > 60
